#include <iostream>
using namespace std;

bool match(const string& r, const string& t, size_t ri = 0, size_t ti = 0) {
    if (ri == r.size()) return ti == t.size();
    if (ri + 1 < r.size() && r[ri + 1] == '*') {
        bool m = match(r, t, ri + 2, ti);
        if (ti < t.size() && (r[ri] == '.' || r[ri] == t[ti]))
            m = m || match(r, t, ri, ti + 1);
        return m;
    }
    if (ti < t.size() && (r[ri] == '.' || r[ri] == t[ti]))
        return match(r, t, ri + 1, ti + 1);
    return false;
}

int main() {
    cout << match("a*b", "b") << endl;
    cout << match("a.b", "axb") << endl;
    cout << match("ab*c", "abc") << endl;
    return 0;
}
